-- MedVerse Rich Clinical Demo Seed
-- Bổ sung dữ liệu dồi dào cho giao diện demo: nhiều bệnh nhân, lịch hẹn, ca khám, bệnh án, đơn thuốc.
-- Chạy sau 02_ai_medications_from_atc.sql và 01_demo_reset_core.sql.
-- =========================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;


CREATE OR REPLACE FUNCTION demo_medication_id(p_code TEXT)
RETURNS UUID AS $$
DECLARE
    med_id UUID;
BEGIN
    IF NOT demo_table_exists('medications') THEN
        RETURN NULL;
    END IF;

    IF demo_column_exists('medications', 'atc_code') THEN
        EXECUTE 'SELECT id FROM medications WHERE atc_code = $1 LIMIT 1' INTO med_id USING p_code;
    ELSIF demo_column_exists('medications', 'code') THEN
        EXECUTE 'SELECT id FROM medications WHERE code = $1 LIMIT 1' INTO med_id USING p_code;
    END IF;

    RETURN med_id;
END;
$$ LANGUAGE plpgsql;

